var timestampField = regexp.MustCompile(`(_at|_time)$`)

// unzonedTimestamps walks a decoded response and reports every field whose name
// marks it as a timestamp but whose value a browser cannot read unambiguously.
func unzonedTimestamps(value any, path string) []string {
	var findings []string
	w http.ResponseWriter,
	id json.RawMessage,
	code int,
	message string,
	data any,
	status int,
) {
	detail := map[string]any{"code": code, "message": message}
	if data != nil {
		detail["data"] = data
	}
	writeJSON(w, status, map[string]any{
		"jsonrpc": "2.0", "id": rawID(id),
		"error": detail,
	})
}

func writeMCPToolError(
	w http.ResponseWriter,
	id json.RawMessage,
	message string,
	protocolVersion string,
) {
	writeMCPResult(w, id, map[string]any{
		"content": []map[string]string{{"type": "text", "text": message}},
		"isError": true,
	}, protocolVersion)
}

func rawID(id json.RawMessage) any {
	if len(id) == 0 {
		return nil
	}
	var value any
	if json.Unmarshal(id, &value) != nil {
		return nil
	}
	return value
}

